#!/bin/bash
# Run every scenario generated by make_case.py.
#   BG_FLOOD : path to the BG_Flood executable (default: BG_Flood on the PATH)
#   NJOBS    : number of scenarios run at the same time (default 1; use >1 on CPU)
#   BG_GPU   : passed to make_case.py, -1 to run on the CPU (default 0 = first GPU)
set -e
cd "$(dirname "$0")"
BG_FLOOD=$(readlink -f "${BG_FLOOD:-$(command -v BG_Flood)}")
NJOBS=${NJOBS:-1}
python3 make_case.py
for d in runs/*/; do
  ( cd "$d" && echo "running $d" && "$BG_FLOOD" BG_param.txt > run.log 2>&1 && echo "done $d" ) &
  while [ "$(jobs -rp | wc -l)" -ge "$NJOBS" ]; do sleep 2; done
done
wait
python3 analyse.py || echo "analyse.py failed"
